h4.sub-tit, .book-chapter-list li
<js>
var list = [];
var els = result;
for (var i in els) {
    if (String(els[i]).match(/sub-tit/)) {
        list.push({
            name: "◤"+els[i].text(),
            url: "",
            volume: true
        });
    } else {
        els[i].select("a").forEach(a => {
            var hasITag = a.select("i").size() > 0;
            var hasIconUnlock = a.select("i.icon-unlock").size() > 0;
            list.push({
                name: a.text(),
                url: a.attr("href")+",{'webView': true}",
                vip: hasITag,
                pay: hasIconUnlock
            });
        });
    }
}
result = list;
</js>

