function login() {
  let une = source.getLoginInfoMap().get("账号")
  let pwd = source.getLoginInfoMap().get("密码")
  if (une && pwd) {
    let body = JSON.stringify({
      username: une,
      password: pwd,
      app: "n"
    })
    let url = source.bookSourceUrl.replace("n.", "auth.") + 'api/v1/auth/login'
    let res = java.post(url, body, {
      "Content-Type": "application/json"
    })
    if (res.body().match(/错误/gi)) {
      throw(res.body())
    }
    //throw(String(res.body()))
    //result = JSON.parse(res.body())

    let header = JSON.stringify({
      "Authorization": "Bearer " + res.body()
    })
    source.putLoginHeader(header)
  }
}

